"1 мая": "1-май",
"12 апреля": "12-апрель",
"12 апреля 1961 года Юрий Гагарин на корабле «Восток-1» стал первым человеком в космосе. Старт был с Байконура. День космонавтики отмечают 12 апреля.": "1961-жили 12-апрелда Юрий Гагарин «Восток-1» кемисидә космосқа чиққан тунҗи адәм болди. Старт Байконурдин берилди. Космонавтика күни 12-апрелда нишанлиниду.",
"13 уроков: исследователь, растения, животные, человек, вещества, воздух, вода, почва, Земля и космос, силы, свет и звук, электричество, магнетизм": "13 дәрис: тәтқиқатчи, өсүмлүкләр, һайванлар, инсан, маддилар, һава, су, тупрақ, Йәр вә космос, күчләр, йоруқлуқ вә аваз, электр, магнитизм",
"4 октября": "4-октябрь",
