"Без растений животным не хватит пищи и укрытий, поэтому их численность уменьшается.": "Өсүмлүксиз һайванларға озуқ вә панаһ йетишмәйду, шуңа уларниң сани азийиду.",
"Бережём воду": "Сувни сақлаймиз",
