"Где магнитная сила больше всего?": "Магнит күчи әң күчлүк қәйәрдә?",
"Где можно почувствовать пульс?": "Пульсни қәйәрдә һес қилиш мумкин?",
"Где можно услышать эхо?": "Садани қәйәрдә аңлаш мумкин?",
"Где на Земле больше всего воды?": "Йәр йүзидә су әң көп қәйәрдә?",
"Где находится космодром Байконур?": "Байконур космодроми қәйәрдә җайлашқан?",
"Где находится орган?": "Әза қәйәрдә җайлашқан?",
"Где находится тень?": "Көләңгә қәйәрдә?",
"Где находятся лёгкие?": "Өпкә қәйәрдә җайлашқан?",
"Где образуются питательные вещества?": "Озуқ маддилар қәйәрдә пәйда болиду?",
"Где питательные вещества всасываются в кровь?": "Озуқ маддилар қәйәрдә қанға сиңиду?",
"Где пища перемешивается и перерабатывается желудочным соком?": "Тамақ қәйәрдә арилишип, меъдә шириси билән ишлиниду?",
