"Звуку нужна среда": "Авазға муһит керәк",
"Звёзды": "Юлтузлар",
"Здоровье зависит от режима дня, питания, сна, движения и чистоты.": "Саламәтлик күн тәртипигә, озуқлинишқа, ухлашқа, һәрикәткә вә тазилиққа бағлиқ.",
"Здоровье защищают мытьё рук, прививки, закаливание, здоровое питание и сон.": "Саламәтликни қол жуюш, прививкилар, чиниқиш, пайдилиқ озуқлиниш вә ухлаш қоғдайду.",
"Здоровье и защита от болезней": "Саламәтлик вә кесәлликтин қоғдиниш",
"Здоровью помогают режим дня, сон, движение, чистота и прививки. Многие инфекции передаются через грязные руки, воздух и воду.": "Саламәтликкә күн тәртиви, ухлаш, һәрикәт, тазилиқ вә прививкилар ярдәм бериду. Нурғун инфекцийәләр чирик қол, һава вә су арқилиқ йуқиду.",
"Зелёный цвет листьям даёт особое вещество — хлорофилл. Оно помогает растению использовать свет.": "Йопурмақларға йешил рәңни алаһидә маддә — хлорофилл бериду. У өсүмлүкниң йоруқлуқтин пайдилинишиға ярдәм бериду.",
"Земля": "Йәр",
"Земля вращается быстрее": "Йәр тезирәк айлиниду",
"Земля вращается вокруг оси": "Йәр оғиниң әтрапида айлиниду",
"Земля вращается вокруг своей оси": "Йәр өз оғиниң әтрапида айлиниду",
"Земля вращается вокруг своей оси за сутки и обходит Солнце за год. Поэтому сменяются день и ночь, времена года.": "Йәр өз оғиниң әтрапида бир түн-күндә айлиниду вә Қуяшни бир жилда айлинип чиқиду. Шуңа күн билән кечә, жил пәсиллири алмишиду.",
"Земля вращается вокруг своей оси и делает один оборот за сутки. Поэтому сменяются день и ночь.": "Йәр өз оғиниң әтрапида айлиниду вә бир айлиниш бир түн-күн болиду. Шуңа күн билән кечә алмишиду.",
"Земля вращается вокруг своей оси.": "Йәр өз оғиниң әтрапида айлиниду.",
"Земля вращается вокруг своей оси. Один оборот занимает сутки. Поэтому сменяются день и ночь.": "Йәр өз оғиниң әтрапида айлиниду. Бир айлиниш бир түн-күн болиду. Шуңа күн билән кечә алмишиду.",
"Земля делает один оборот вокруг Солнца за сутки.": "Йәр Қуяшни бир түн-күндә бир қетим айлинип чиқиду.",
"Земля и космос — Білім Аралы": "Йәр вә космос — Білім Аралы",
"Земля имеет форму шара.": "Йәрниң шәкли шар.",
"Земля имеет форму шара. Модель Земли — глобус. На нём есть полюса и экватор.": "Йәрниң шәкли шар. Йәрниң моделы — глобус. Униңда қутуплар вә экватор бар.",
"Земля обращается вокруг Солнца": "Йәр Қуяш әтрапида айлиниду",
"Земля обходит Солнце, а ось наклонена": "Йәр Қуяшни айлиниду, оқи болса егиз",
"Земля останавливается": "Йәр тохтап қалиду",
"Земля поворачивается к Солнцу": "Йәр Қуяшқа қарап бурулиду",
"Земля поворачивается от Солнца": "Йәр Қуяштин бурулуп кетиду",
"Земля притягивает все тела": "Йәр барлиқ җисимларни тартиду",
"Земля улетает от Солнца": "Йәр Қуяштин учуп кетиду",
"Земля — большой магнит": "Йәр — чоң магнит",
"Земля — большой магнит. Стрелка компаса поворачивается к северу.": "Йәр — чоң магнит. Компас стрелкиси шималға бурулиду.",
"Земная кора": "Йәр қобуғи",
"Зеркало отражает свет.": "Ойна йоруқлуқни қайтуриду.",
"Зеркало хорошо отражает свет.": "Ойна йоруқлуқни яхши қайтуриду.",
"Знать главные события освоения космоса и планеты Солнечной системы": "Космосни өзләштүришниң асасий вақиәлирини вә Қуяш системисиниң планетилирини билиш",
"Знать способы очистки воды и правила её экономии": "Сувни тазилаш усуллирини вә уни тежәш қаидилирини билиш",
"Знать, как беречь здоровье и защищаться от инфекций": "Саламәтликни қандақ сақлашни вә инфекцийәдин қандақ қоғдинишни билиш",
"Знать, что такое Красная книга, и объяснять, как люди влияют на растения и животных": "Қизил китап немә екәнлигини билиш вә адәмләрниң өсүмлүк вә һайванларға қандақ тәсир қилидиғинини чүшәндүрүш",
