"Из чего состоит почва?": "Тупрақ немидин тәркиб тапқан?",
"Из-за силы тяжести предметы падают.": "Еғирлиқ күчи сәвәвидин нәрсиләр чүшиду.",
"Из-за чего это происходит?": "Бу немә сәвәбтин болиду?",
"Иммунитет — защита организма от болезней.": "Иммунитет — организмниң кесәлликтин қоғдилиши.",
"Иммунитет — защита организма от болезней. Его укрепляют закаливание, движение, овощи и фрукты.": "Иммунитет — организмниң кесәлликтин қоғдилиши. Уни чиниқиш, һәрикәт, көктат вә мевә мустәһкәмләйду.",
"Интернет": "Интернет",
"Информацию из интернета всегда можно принимать без проверки.": "Интернеттики мәлуматни һемишә тәкшүрмәй қобул қилишқа болиду.",
"Информацию можно найти в книгах, энциклопедиях, журналах, в интернете, а ещё спросить у специалиста или увидеть самому.": "Мәлуматни китапларда, энциклопедийәләрдә, журналларда, интернетта тепишқа болиду, йәнә мутәхәссистин сорашқа яки өзи көрүшкә болиду.",
