"Источники света светят сами: Солнце, лампа, свеча, костёр. Луна и зеркало не источники, они отражают свет.": "Йоруқлуқ мәнбәлири өзи йорутиду: Қуяш, чирақ, шам, от. Ай билән ойна мәнбә әмәс, улар йоруқлуқни қайтуриду.",
