"Как называется незаконная охота?": "Қанунсиз ов немә дәп атилиду?",
"Как называется образование питательных веществ в листьях на свету?": "Йопурмақларда йоруқлуқта озуқ маддиларниң пәйда болуши немә дәп атилиду?",
