"Как называется процесс переработки пищи?": "Тамақни ишләш жәрияни немә дәп атилиду?",
"Как называется путь воды: испарение, облака, дождь?": "Судин айлиниш йоли: буғлиниш, булутлар, ямғур немә дәп атилиду?",
