"Как называют вещества, которые не проводят ток?": "Ток өткүзмәйдиған маддилар немә дәп атилиду?",
"Как называют вещества, не проводящие ток?": "Ток өткүзмәйдиған маддилар немә дәп атилиду?",
"Как называют воображаемую линию, вокруг которой вращается Земля?": "Йәр айлинидиған хиялий сизиқ немә дәп атилиду?",
