"Красная книга — это список редких и исчезающих видов.": "Қизил китап — сийрәк вә йоқиливатқан түрләр тизимлики.",
"Красный цвет книги — цвет праздника.": "Китапниң қизил рәңги — байрам рәңги.",
"Красный цвет — как сигнал тревоги: этим растениям и животным грозит исчезновение.": "Қизил рәң — һошийарлиқ бәлгүси кәби: бу өсүмлүк вә һайванлар йоқилиш хәвпи астида.",
"Кровообращение": "Қан айлиниши",
"Кровь разносит по телу кислород и питательные вещества и уносит ненужное. Красный цвет ей дают красные клетки крови.": "Қан кислород вә озуқ маддиларни пүткүл тәнгә тарқитиду, керәксизини елип кетиду. Униңға қизил рәңни қанниң қизил һужәйрилири бериду.",
"Кровь разносит по телу кислород.": "Қан кислородни пүткүл тәнгә тарқитиду.",
"Кровь течёт по сосудам ко всем органам": "Қан тамурлар арқилиқ барлиқ әзаларға еқиду",
"Кровь течёт по сосудам: артерии, вены и тонкие капилляры. Вместе сердце, кровь и сосуды — кровеносная система.": "Қан тамурлар арқилиқ еқиду: артерийәләр, вениләр вә нәзик капиллярлар. Жүрәк, қан вә тамурлар биллә — қан айлиниш системиси.",
"Кровь течёт только по лёгким.": "Қан пәқәт өпкә арқилиқ еқиду.",
"Крот живёт в почве.": "Көрсичан тупрақта яшайду.",
"Крот роет ходы под землёй": "Көрсичан йәр астида йол қазиду",
"Кто в цепи «трава → суслик → орёл» хищник?": "«от → суслик → бүркүт» зәнҗиридә йиртқуч ким?",
"Кто в цепи питания идёт первым?": "Озуқ зәнҗиридә биринчи ким кәлгән?",
"Кто жертва в паре «волк — заяц»?": "«бөрә — қуян» жүпидә қурбан ким?",
"Кто из казахстанцев летал в космос?": "Қазақстанлиқларниң қайсиси космосқа учқан?",
"Кто из этих животных беспозвоночное?": "Бу һайванларниң қайсиси умуртқисиз?",
"Кто из этих животных хищник?": "Бу һайванларниң қайсиси йиртқуч?",
"Кто или что?": "Ким яки немә?",
"Кто опыляет цветы?": "Гүлләрни ким чаңлитиду?",
"Кто относится к беспозвоночным?": "Умуртқисизларға ким тәвә?",
"Кто охраняет природу на особых территориях?": "Алаһидә худудларда тәбиәтни ким қоғдайду?",
"Кто первая женщина в космосе?": "Космосқа чиққан тунҗи аял ким?",
"Кто первым вышел в открытый космос?": "Очуқ космосқа биринчи болуп ким чиқти?",
