"Кто разрыхляет почву?": "Тупрақни ким йумшитиду?",
"Кто рыхлит почву?": "Тупрақни ким йумшитиду?",
"Кто стал первым человеком в космосе?": "Космосқа чиққан тунҗи инсан ким болди?",
"Кто такие паразиты?": "Паразитлар ким?",
"Кто такой хищник?": "Йиртқуч ким?",
"Кто это в цепи питания?": "Бу озуқ зәнҗиридә ким?",
"Куда направлена сила трения при движении?": "Һәрикәттә сүркилиш күчи қайси тәрәпкә йөнәлгән?",
"Куда направлена сила тяжести?": "Еғирлиқ күчи қайси тәрәпкә йөнәлгән?",
