"Лампочка — потребитель в цепи.": "Чирақ — чеңбәрдики истемалчи.",
"Лампочка — потребитель электричества.": "Чирақ — электр истемалчиси.",
"Лекарства можно принимать без разрешения взрослых.": "Дориларни чоңларниң рухситисиз ичишкә болиду.",
"Лесополосы защищают почву от ветра.": "Ормам йоллири тупрақни шамалдин қоғдайду.",
"Лист улавливает свет, берёт из воздуха углекислый газ и выделяет кислород.": "Йопурмақ йоруқлуқни тутиду, һавадин көмүр кислота газини алиду вә кислород чиқириду.",
"Листья берут воду из почвы.": "Йопурмақлар тупрақтин су алиду.",
"Листья и фотосинтез": "Йопурмақлар вә фотосинтез",
"Литосфера": "Литосфера",
"Литосфера — твёрдая оболочка, гидросфера — водная, атмосфера — воздушная, биосфера — живая.": "Литосфера — қаттиқ қобуқ, гидросфера — су қобуғи, атмосфера — һава қобуғи, биосфера — тирик қобуқ.",
"Луна закрывает Солнце": "Ай Қуяшни йепиду",
