"Луна отражает свет Солнца": "Ай Қуяшниң йоруқлуқини қайтуриду",
"Луна сама не светится": "Ай өзи йорумайду",
"Луна светит сама.": "Ай өзи йоруйду.",
"Луна светит собственным светом.": "Ай өз йоруқлуқи билән йоруйду.",
"Луна — звезда.": "Ай — юлтуз.",
"Луна — планета.": "Ай — планета.",
"Луна — спутник Земли": "Ай — Йәрниң һәмраһи",
"Луна — спутник Земли.": "Ай — Йәрниң һәмраһи.",
"Луна — спутник Земли. Она обращается вокруг Земли примерно за месяц и светит отражённым светом Солнца.": "Ай — Йәрниң һәмраһи. У Йәр әтрапида тәхминән бир айда айлиниду вә Қуяшниң қайтурулған йоруқлуқи билән йоруйду.",
"Луна-1": "Луна-1",
"Любая цепь питания начинается с растения. Растения создают питательные вещества на свету.": "Һәр қандақ озуқ зәнҗири өсүмлүктин башлиниду. Өсүмлүкләр йоруқлуқта озуқ маддиларни пәйда қилиду.",
"Люди могут и вредить, и помогать природе": "Адәмләр тәбиәткә зиянму, ярдәмму қилиши мумкин",
