"Лёгкие нужны для пищеварения.": "Өпкә һәзим қилиш үчүн керәк.",
"Лёд плавится": "Муз еришиду",
"Лёд тает и становится водой, вода испаряется и становится паром, пар охлаждается и снова превращается в воду.": "Муз еришип су болиду, су буғлинип буғ болиду, буғ совуп йәнә су болиду.",
