"Магнетизм — Білім Аралы": "Магнитизм — Білім Аралы",
"Магнит действует через бумагу, стекло, воду и даже тонкую доску.": "Магнит қәғәз, айнәк, су вә һәтта нәзик тахтайму арқилиқ тәсир қилиду.",
"Магнит действует через бумагу.": "Магнит қәғәз арқилиқ тәсир қилиду.",
"Магнит и намагничивание": "Магнит вә магнитлаш",
"Магнит можно размагнитить ударами.": "Магнитни урушлар билән магнитсизландурушқа болиду.",
"Магнит притягивает алюминиевую фольгу.": "Магнит алюминий фольгиниси тартиду.",
"Магнит притягивает без прикосновения. Нажимай на карточки и узнавай, как он действует.": "Магнит тегмәйла тартиду. Карточкиларни бесип, униң қандақ тәсир қилидиғинини билиң.",
"Магнит притягивает дерево.": "Магнит яғачни тартиду.",
"Магнит притягивает железо и сталь": "Магнит төмүр вә пулатни тартиду",
"Магнит притягивает железо и сталь. Пластмасса, дерево, стекло, бумага и алюминий не притягиваются.": "Магнит төмүр вә пулатни тартиду. Пластмасса, яғач, айнәк, қәғәз вә алюминий тартилмайду.",
"Магнит притягивает железо и сталь. Разноимённые полюса притягиваются, одноимённые отталкиваются.": "Магнит төмүр вә пулатни тартиду. Охшимайдиған қутуплар тартишиду, охшаш қутуплар иттиришиду.",
"Магнит притягивает железо, сталь, никель. Дерево, пластик, стекло, медь, алюминий он не притягивает.": "Магнит төмүр, пулат, никельни тартиду. Яғач, пластик, айнәк, мис, алюминийни тартмайду.",
"Магнит притягивает железо.": "Магнит төмүрни тартиду.",
"Магнит притягивает пластмассу.": "Магнит пластмассини тартиду.",
