"Масло делает поверхность скользкой": "Май бетини сирғинақ қилиду",
"Медицина": "Медицина",
"Медь — проводник тока.": "Мис — ток өткүзгүч.",
"Мелкие листья помогают меньше испарять воду.": "Майда йопурмақлар сувниң аз буғлинишиға ярдәм бериду.",
"Металл проводит электрический ток.": "Металл электр токини өткүзиду.",
"Металлы и вода с солью проводят ток. Резина, пластик, стекло и сухое дерево не проводят — это изоляторы.": "Металлар вә тузлуқ су ток өткүзиду. Резина, пластик, айнәк вә қуруқ яғач өткүзмәйду — булар изоляторлар.",
"Металлы проводят ток, а резина и пластмасса не проводят.": "Металлар ток өткүзиду, резина билән пластмасса өткүзмәйду.",
"Металлы проводят электрический ток. Резина, пластик и стекло ток не проводят — их называют изоляторами.": "Металлар электр токини өткүзиду. Резина, пластик вә айнәк ток өткүзмәйду — уларни изоляторлар дәйду.",
"Металлы хорошо проводят тепло.": "Металлар иссиқни яхши өткүзиду.",
"Металлы хорошо проводят тепло: железная ложка в горячем чае быстро нагревается. Дерево и пластик проводят тепло плохо.": "Металлар иссиқни яхши өткүзиду: төмүр қошуқ иссиқ чайда тез қизийду. Яғач билән пластик иссиқни начар өткүзиду.",
"Микробы вызывают инфекционные болезни.": "Микроблар йуқумлуқ кесәлликләрни кәлтүрүп чиқириду.",
"Микробы погибают": "Микроблар өлиду",
"Микроскоп увеличивает мелкие предметы": "Микроскоп майда нәрсиләрни чоңайтиду",
"Млекопитающие": "Сүт эмгүчиләр",
"Млекопитающие выкармливают детёнышей молоком. У птиц есть перья и крылья. У рыб — жабры и чешуя. Лягушки — земноводные. Ящерицы и змеи — пресмыкающиеся.": "Сүт эмгүчиләр балилирини сүт билән беқиду. Қушларда пәрләр вә қанатлар бар. Балиқларда желә вә пулақ бар. Бақилар — қуруқлуқ-су һайванлири. Кәлтә вә йиланлар — сүркилгүчиләр.",
"Можно": "Болиду",
"Можно ли принимать лекарства без разрешения взрослых?": "Дориларни чоңларниң рухситисиз ичишкә боламду?",
"Можно также позвонить по номеру 112": "Йәнә 112 номуриға тәлипон қилишқиму болиду",
"Мокрыми руками можно включать электроприборы.": "Ислақ қол билән электр җиһазлирини қошушқа болиду.",
"Морскую воду нельзя пить без специальной очистки.": "Деңиз сувини алаһидә тазилимай ичишкә болмайду.",
"Мусор в водоём не вредит воде.": "Су ховузиға ташланған ахмақ сувға зиян қилмайду.",
"Мы живём на земной коре.": "Биз йәр қобуғида яшаймиз.",
"Мыть руки перед едой не обязательно.": "Тамақ алдида қол жуюш шәрт әмәс.",
"Мыть руки с мылом полезно.": "Сапун билән қол жуюш пайдилиқ.",
"Мытьё рук смывает микробы": "Қол жуюш микробларни жуюп кетиду",
"На Международной космической станции работают космонавты разных стран. Телескопы помогают изучать звёзды и планеты.": "Хәлқара космос станциясидә һәр хил әлләрниң космонавтлири ишләйду. Телескоплар юлтуз вә планетиларни үгинишкә ярдәм бериду.",
"На земле и в воздухе": "Йәрдә вә һавада",
"На одежду детей прикрепляют светоотражающие знаки — фликеры. В темноте они хорошо видны водителям.": "Балиларниң кийимигә йоруқлуқ қайтурғуч бәлгүләр — фликерләр тагланиду. Қараңғулуқта улар һайдигучиларға яхши көрүниду.",
"На свету в зелёных листьях из воды и углекислого газа образуются питательные вещества и выделяется кислород. Этот процесс называют фотосинтезом.": "Йешил йопурмақларда йоруқлуқта судин вә көмүр кислота газидин озуқ маддилар пәйда болиду вә кислород чиқиду. Бу жәриян фотосинтез дәп атилиду.",
"На свету в зелёных листьях из воды и углекислого газа образуются питательные вещества, и выделяется кислород.": "Йешил йопурмақларда йоруқлуқта судин вә көмүр кислота газидин озуқ маддилар пәйда болиду, вә кислород чиқиду.",
