"Описывать вещества по их свойствам": "Маддиләрни хусусийәтлири бойичә тәсвирләш",
"Описывать источники энергии и простые цепи": "Энергийә мәнбәлирини вә оддий чеңбәрләрни тәсвирләш",
"Описывать путь воздуха и работу сердца и крови": "Һаваниң йолини вә жүрәк билән қанниң ишлишини тәсвирләш",
"Описывать путь пищи по органам пищеварения": "Тамақниң һәзим қилиш әзалири бойичә йолини тәсвирләш",
"Описывать системы органов человека и защиту от болезней": "Инсанниң әза системилирини вә кесәлликтин қоғдинишни тәсвирләш",
"Описывать состав воздуха и условия горения": "Һаваниң тәркивини вә янғанниң шәртлирини тәсвирләш",
"Описывать состав почвы и виды почв Казахстана": "Тупрақниң тәркивини вә Қазақстан тупрақ түрлирини тәсвирләш",
"Описывать среду обитания и взаимоотношения животных": "Яшаш муһитини вә һайванларниң мунасивәтлирини тәсвирләш",
"Описывать строение Земли и следствия вращения": "Йәрниң түзүлүшини вә айлиниш нәтижилирини тәсвирләш",
"Описывать сферы Земли и следствия вращения Земли": "Йәрниң қобуқлирини вә Йәрниң айлиниш нәтижилирини тәсвирләш",
