"Паук — это насекомое.": "Өмүчүк — һашарәт.",
"Первый спутник запустили в 1991 году.": "Тунҗи һәмраһ 1991-жили учурулди.",
"Первый человек в космосе — Юрий Гагарин.": "Космосқа чиққан тунҗи инсан — Юрий Гагарин.",
"Первым человеком в космосе был Юрий Гагарин.": "Космосқа чиққан тунҗи инсан Юрий Гагарин болди.",
"Перегной делает почву плодородной.": "Гумус тупрақни түгүмдар қилиду.",
"Перегной образуется из остатков растений и животных.": "Гумус өсүмлүк вә һайванларниң қалдуқлиридин пәйда болиду.",
"Перегной образуется из остатков растений и животных. Его создают бактерии и грибы.": "Гумус өсүмлүк вә һайванларниң қалдуқлиридин пәйда болиду. Уни бактерийәләр вә замбурғлар пәйда қилиду.",
"Перегной образуется из остатков растений и животных. Он делает почву тёмной и плодородной.": "Гумус өсүмлүк вә һайванларниң қалдуқлиридин пәйда болиду. У тупрақни қараңғу вә түгүмдар қилиду.",
"Перед едой не нужно мыть руки.": "Тамақ алдида қол жуюш керәк әмәс.",
"Перед опытом": "Тәҗрибидин бурун",
"Перед опытом ставим вопрос, делаем предположение, составляем план и готовим материалы.": "Тәҗрибидин бурун соал қоюмиз, пәрәз қилимиз, пилан түзимиз вә материалларни тәйярлаймиз.",
"Песок быстро пропускает воду": "Қум сувни тез өткүзиду",
"Песок растворяется в воде.": "Қум сувда еришиду.",
"Песок хорошо удерживает воду.": "Қум сувни яхши тутиду.",
"Песок — живая часть почвы.": "Қум — тупрақниң тирик қисми.",
"Песчаная почва хорошо пропускает воду, но плохо её держит. Глинистая почва держит воду, но плохо пропускает воздух.": "Қумлуқ тупрақ сувни яхши өткүзиду, лекин уни начар тутиду. Лайлиқ тупрақ сувни тутиду, лекин һавани начар өткүзиду.",
"Питательные вещества всасываются в кровь в тонкой кишке.": "Озуқ маддилар нәзик ичәктә қанға сиңиду.",
"Питательные вещества образуются в корнях.": "Озуқ маддилар йилтизларда пәйда болиду.",
"Пища даёт организму энергию и вещества для роста. Она должна быть переработана — это называется пищеварением.": "Озуқ организмға энергийә вә өсүш үчүн маддә бериду. У ишлиниши керәк — буни һәзим дәйду.",
"Пища даёт организму энергию.": "Озуқ организмға энергийә бериду.",
"Пища проходит путь: рот → пищевод → желудок → тонкая кишка → толстая кишка. Питательные вещества всасываются в кровь.": "Тамақ мундақ йол өтиду: ағиз → қизил өңәч → меъдә → нәзик ичәк → йоған ичәк. Озуқ маддилар қанға сиңиду.",
"Пища проходит рот, пищевод, желудок и кишечник. Так организм получает энергию.": "Тамақ ағиз, қизил өңәч, меъдә вә ичәктин өтиду. Шундақ қилип организм энергийә алиду.",
"Пища сразу попадает из рта в кишечник.": "Тамақ ағиздин тоғра ичәккә кириду.",
"Пищеварение": "Һәзим",
"Пищеварение начинается во рту.": "Һәзим ағизда башлиниду.",
"Пищеварительный": "Һәзим қилишқа тәвә",
"Пищевод соединяет рот и желудок.": "Қизил өңәч ағиз билән меъдини улайду.",
"Пищу надо тщательно жевать. Нужно мыть руки перед едой, есть вовремя и разнообразно, не переедать.": "Тамақни яхши чәйнәш керәк. Тамақ алдида қол жуюш, вақтида вә хилму-хил йейиш, көп йемәслик керәк.",
"Пищу нужно тщательно жевать.": "Тамақни яхши чәйнәш керәк.",
