"Плесецк": "Плесецк",
"Плодородие повышают дождевые черви, перегной, правильный полив и рыхление.": "Түгүмдарлиқни йәр қуртлири, гумус, тоғра сугириш вә йумшитиш ашуриду.",
"Плодородие почвы зависит от перегноя. Самые плодородные почвы — чернозёмы.": "Тупрақниң түгүмдарлиқи гумусқа бағлиқ. Әң түгүмдар тупрақлар — қара тупрақлар (чернозём).",
"Плодородие почвы не зависит от её состава.": "Тупрақниң түгүмдарлиқи униң тәркивигә бағлиқ әмәс.",
"Плодородие — способность почвы давать растениям всё необходимое для жизни.": "Түгүмдарлиқ — тупрақниң өсүмлүкләргә һаят үчүн керәклик һәммини бериш қабилийити.",
"Плодородие — способность почвы давать урожай. Самый плодородный — чернозём.": "Түгүмдарлиқ — тупрақниң һосул бериш қабилийити. Әң түгүмдар — қара тупрақ.",
