"Повышает плодородие": "Түгүмдарлиқни ашуриду",
"Под ногами у нас живая почва. Нажимай на карточки и узнавай, из чего она состоит.": "Путимиз астида тирик тупрақ бар. Карточкиларни бесип, униң немидин тәркиб тапқанлиғини билиң.",
"Подумай, к какой группе относится каждая карточка.": "Һәр бир карточка қайси гурупқа тәвә екәнлигини ойлап көр.",
"Пожары могут навредить растениям и животным.": "Өрт өсүмлүк вә һайванларға зиян йәткүзүши мумкин.",
"Позвоночник — главный признак позвоночных": "Умуртқа — умуртқилиқларниң асасий бәлгүси",
