"После опыта": "Тәҗрибидин кейин",
"После опыта сравниваем результат с предположением и делаем вывод: что мы узнали.": "Тәҗрибидин кейин нәтижини пәрәз билән селиштуримиз вә хуласә чиқиримиз: немини билдуқ.",
