"Притянутся": "Тартилиду",
"Провода делают из меди и алюминия": "Симларни мис вә алюминийдин ясайду",
"Проводник": "Өткүзгүч",
"Прозрачные предметы (стекло, вода) пропускают свет, непрозрачные (дерево, металл, картон) не пропускают, а полупрозрачные (калька) пропускают не весь свет.": "Шәффаф нәрсиләр (айнәк, су) йоруқлуқни өткүзиду, шәффаф әмәсләр (яғач, металл, картон) өткүзмәйду, йерим шәффафлар (калька) йоруқлуқниң һәммисини әмәс өткүзиду.",
"Прозрачный": "Шәффаф",
"Пропускает ли свет?": "Йоруқлуқни өткүзәмду?",
"Пропускают свет": "Йоруқлуқни өткүзиду",
