"Пружина — пример действия силы упругости.": "Пружина — серпилма күч тәсириниң мисали.",
"Птицы выкармливают детёнышей молоком.": "Қушлар балилирини сүт билән беқиду.",
"Птицы могут разносить семена.": "Қушлар уруқни тарқитиши мумкин.",
"Пульс можно почувствовать на запястье.": "Пульсни биләктә һес қилишқа болиду.",
"Пульс — толчки крови в сосудах при работе сердца. Его можно почувствовать на запястье. При беге сердце бьётся быстрее.": "Пульс — жүрәк ишлигәндә қан тамурлиридики соқушлар. Уни биләктә һес қилишқа болиду. Жүгүргәндә жүрәк тезирәк соқиду.",
"Пчела и цветок помогают друг другу.": "Һәрә билән гүл бир-биригә ярдәм бериду.",
"Пыль — тоже часть воздуха.": "Чаңму һаваниң бир қисми.",
